-- Sol'Azeroth v3, F5d : sans guildes ni banques, Durotar sans PNJ d'ambiance, sans hauts faits natifs.
-- Généré par outils\sans_guildes.py : ne pas modifier à la main.
USE acore_world;

-- Banquiers, guildes, tabards : drapeaux retirés (sauvegarde pour la migration descendante).
CREATE TABLE IF NOT EXISTS solazeroth_v3_drapeaux_origine (genre VARCHAR(8) NOT NULL, cle INT UNSIGNED NOT NULL, npcflag INT UNSIGNED NOT NULL, PRIMARY KEY (genre, cle));
INSERT IGNORE INTO solazeroth_v3_drapeaux_origine SELECT 'modele', entry, npcflag FROM creature_template WHERE npcflag & 9306112;
INSERT IGNORE INTO solazeroth_v3_drapeaux_origine SELECT 'apparition', guid, npcflag FROM creature WHERE npcflag & 9306112;
UPDATE creature_template SET npcflag = npcflag & ~9306112 WHERE npcflag & 9306112;
UPDATE creature SET npcflag = npcflag & ~9306112 WHERE npcflag & 9306112;

-- Coffres de guilde et PNJ d'ambiance de Durotar : cachés par la phase.
CREATE TABLE IF NOT EXISTS solazeroth_v3_phases_origine (genre VARCHAR(8) NOT NULL, guid INT UNSIGNED NOT NULL, phaseMask INT UNSIGNED NOT NULL, PRIMARY KEY (genre, guid));
INSERT IGNORE INTO solazeroth_v3_phases_origine SELECT 'objet', g.guid, g.phaseMask FROM gameobject g JOIN gameobject_template t ON t.entry = g.id WHERE t.type = 34;
UPDATE gameobject g JOIN gameobject_template t ON t.entry = g.id SET g.phaseMask = 1073741824 WHERE t.type = 34;
INSERT IGNORE INTO solazeroth_v3_phases_origine SELECT 'pnj', guid, phaseMask FROM creature WHERE guid IN (5303, 6378, 6379, 7286, 7288, 7664, 3367, 7944, 7947, 10349, 1976136, 1976137, 1976138, 1976139, 1976187, 1976188);
UPDATE creature SET phaseMask = 1073741824 WHERE guid IN (5303, 6378, 6379, 7286, 7288, 7664, 3367, 7944, 7947, 10349, 1976136, 1976137, 1976138, 1976139, 1976187, 1976188);

